//! The generators: schema data in, source files out.
//!
//! Each generator emits a whole file, including the `DO NOT EDIT` header naming
//! the regeneration command. Output is COMMITTED and checked by a test rather
//! than produced by a `build.rs` — see the scaffold doc §4 for the decision and
//! the evidence behind it.
//!
//! A generated `.rs` file is subject to `cargo fmt --all -- --check`, so every
//! emitter here must produce output that is already a fixed point of rustfmt.
//! That is an acceptance property, not a nicety: if it drifts, the format gate
//! and the golden gate fight each other.

pub mod adapter_rs;
pub mod decl_rs;
pub mod handler_rs;
pub mod wire_rs;

use crate::schema::Effect;

/// One file this crate owns end to end.
#[derive(Clone, Debug)]
pub struct GeneratedFile {
    /// Path relative to the workspace root.
    pub path: String,
    /// The complete file contents.
    pub contents: String,
}

/// Escape a string for emission as a Rust string literal.
///
/// Deliberately minimal: the effect contract's text is Haskell source and
/// English prose, so only quotes, backslashes and newlines occur. Anything else
/// passes through verbatim, which keeps non-ASCII (the em-dashes in the helper
/// docs) as itself rather than as an escape — matching how the hand-written
/// registry spells it.
#[must_use]
pub fn rust_string_literal(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

/// The header every generated file carries, as line comments using `prefix`.
#[must_use]
pub fn header(prefix: &str, what: &str) -> String {
    let lines = [
        format!("{what} — GENERATED by tidepool-protocol. DO NOT EDIT BY HAND."),
        String::new(),
        "The schema in `tidepool-protocol/src/effects/` is the single source of".to_string(),
        "truth for this effect's contract. Regenerate with:".to_string(),
        String::new(),
        "    cargo run -p tidepool-protocol --bin tidepool-protocol-gen".to_string(),
        String::new(),
        "and verify with `cargo nextest run -p tidepool-protocol` (the".to_string(),
        "`generated_files_are_current` test), or rewrite in place with".to_string(),
        "`TIDEPOOL_REGEN_PROTOCOL=1`.".to_string(),
    ];
    let mut out = String::new();
    for l in lines {
        if l.is_empty() {
            out.push_str(prefix.trim_end());
        } else {
            out.push_str(prefix);
            out.push_str(&l);
        }
        out.push('\n');
    }
    out
}

/// Every file generated for `effects`, in a stable order.
///
/// The wire and adapter files are emitted only for an effect that actually has
/// something to put in them — a `type_defs` vocabulary, and a `DomainMap` on at
/// least one entry. That is not a special case for one effect: Exec and Journal
/// have empty `type_defs`, so they get no wire module and no adapter module, and
/// an empty generated file would be worse than none.
#[must_use]
pub fn all_files(effects: &[Effect]) -> Vec<GeneratedFile> {
    let mut out = Vec::new();
    for e in effects {
        out.push(decl_rs::file(e));
        out.push(handler_rs::file(e));
        if wire_rs::has_wire_types(e) {
            out.push(wire_rs::file(e));
        }
        if adapter_rs::has_adapters(e) {
            out.push(adapter_rs::file(e));
        }
    }
    out.push(decl_rs::module_index(effects));
    out.push(handler_rs::module_index(effects));
    if effects.iter().any(wire_rs::has_wire_types) {
        out.push(wire_rs::module_index(effects));
    }
    out
}

/// The snake_case module name an effect's generated files live under.
#[must_use]
pub fn module_name(e: &Effect) -> String {
    let mut out = String::new();
    for (i, c) in e.name.chars().enumerate() {
        if c.is_uppercase() {
            if i != 0 {
                out.push('_');
            }
            out.extend(c.to_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

/// The shared `mod`-index body for a directory of generated effect modules.
///
/// `flatten` adds a re-export glob per module. The decl side wants it (the
/// crate root does `pub use generated::*`, so `tidepool_mcp::exec_decl` keeps
/// its path); the handler side does not (each effect's own module re-exports
/// its types, so a second glob here would just be an unused import).
fn index_body(prefix_what: &str, modules: &[String], flatten: bool) -> String {
    let mut out = header("//! ", prefix_what);
    out.push('\n');
    let mut names: Vec<String> = modules.to_vec();
    names.sort();
    for n in &names {
        out.push_str(&format!("pub mod {n};\n"));
    }
    if flatten {
        out.push('\n');
        for n in &names {
            out.push_str(&format!("pub use {n}::*;\n"));
        }
    }
    out
}
